nl_msg_put_unspec(struct ofpbuf *msg, uint16_t type,
                  const void *data, size_t size)
{
    void *ptr;

    ptr = nl_msg_put_unspec_uninit(msg, type, size);
    nullable_memcpy(ptr, data, size);
}

